import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property through to the executor unchanged, once', async () => {
    const registry = new ToolRegistry();
    const received: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}, unit: {type: 'string', enum: ['c', 'f'], default: 'c'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {location: 'Oslo', extra: 1});

    expect({received, result: response.result}).toEqual({
      received: [{location: 'Oslo', extra: 1}],
      result: 'sunny',
    });
  });
});
